var now = new Date();
var history = flow.get('history') || [];

// Simulate a realistic count based on hour of day
var hour = now.getHours();
var base = (hour >= 8 && hour <= 17) ? 8 : 2;
var simCount = Math.floor(Math.random() * base) + 1;

var entry = {
    timestamp: new Date(now.getFullYear(), now.getMonth(), now.getDate(), hour, 0, 0)
                  .toISOString().slice(0,19),
    count: simCount
};
history.push(entry);
if (history.length > 336) history = history.slice(history.length - 336);
flow.set('history', history);

// Output 1: for display nodes
var displayMsg = {
    payload: {
        timestamp: entry.timestamp,
        count: simCount
    },
    topic: 'check_in'
};

// Output 2: for text widget
var textMsg = {
    payload: entry.timestamp + '   count: ' + simCount
};

return [displayMsg, textMsg];

var history = flow.get('history') || [];
if (history.length < 24) {
    node.status({fill:'yellow', shape:'ring', text:'waiting for history (' + history.length + '/24)'});
    return null;
}

var now = new Date();
var tomorrow = new Date(now);
tomorrow.setDate(tomorrow.getDate() + 1);
var yyyy = tomorrow.getFullYear();
var mm   = String(tomorrow.getMonth() + 1).padStart(2,'0');
var dd   = String(tomorrow.getDate()).padStart(2,'0');

node.status({fill:'blue', shape:'dot', text:'requesting forecast for ' + yyyy+'-'+mm+'-'+dd});

msg.payload = {
    date   : yyyy + '-' + mm + '-' + dd,
    history: history
};
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// If Flask is not running, statusCode will be undefined or an error object
if (msg.statusCode !== 200 || !msg.payload || !msg.payload.forecasts) {
    var errText = (msg.payload && msg.payload.error)
        ? msg.payload.error
        : 'Flask service not reachable. Start it with: .\\venv\\Scripts\\python src\\predict_service.py';
    node.error(errText, msg);
    node.status({fill:'red', shape:'dot', text:'Flask unreachable'});

    // Send error text to dashboard status widget
    var errMsg = { payload: '⚠ ' + errText };
    return [null, errMsg];
}

node.status({fill:'green', shape:'dot', text:'OK ' + new Date().toLocaleTimeString()});
return [msg, null];

var forecasts = msg.payload.forecasts;
var date      = msg.payload.date;

// node-red-dashboard ui_chart expects:
//   msg.payload = [ { series:[label], data:[{x,y},...] } ]
// OR the simpler array-of-values form when labels are set via msg.labels

var labels = forecasts.map(function(f){ return f.hour + ':00'; });
var values = forecasts.map(function(f){ return f.predicted_count; });

// Format for ui_chart bar chart
msg.payload = [{ label: date, data: values }];
msg.labels  = labels;
msg.topic   = date;

// Also update status text
var statusMsg = { payload: 'Forecast for ' + date + ' loaded (' + values.length + ' hours)' };

return msg;
